{
  "pipeline_id": "rna-seq-analysis",
  "name": "RNA-seq Differential Expression Analysis",
  "description": "End-to-end RNA-seq pipeline from raw paired-end FASTQ to differential gene expression. FastQC quality control, Trimmomatic adapter trimming, HISAT2 splice-aware alignment, SAMtools sorting, featureCounts quantification, and DESeq2 differential expression. Produces a real count matrix and a ranked DE table.",
  "estimated_duration": "2-5 hours",
  "inputs": [
    {
      "name": "inputFastqR1",
      "type": "file",
      "required": true,
      "description": "Read 1 FASTQ file (.fastq.gz)"
    },
    {
      "name": "inputFastqR2",
      "type": "file",
      "required": true,
      "description": "Read 2 FASTQ file (.fastq.gz) — omit for single-end"
    },
    {
      "name": "referenceGenome",
      "type": "string",
      "required": false,
      "default": "references/GRCh38/hg38.fa",
      "description": "Reference genome FASTA (GRCh38 or other)"
    },
    {
      "name": "annotationGtf",
      "type": "file",
      "required": false,
      "default": "references/GRCh38/hg38.refGene.gtf",
      "description": "Gene annotation GTF file"
    },
    {
      "name": "sampleName",
      "type": "string",
      "required": false,
      "default": "sample",
      "description": "Sample identifier"
    },
    {
      "name": "strandedness",
      "type": "select",
      "required": false,
      "default": "0",
      "options": [
        "0",
        "1",
        "2"
      ],
      "description": "Library strandedness: 0 unstranded, 1 stranded, 2 reverse-stranded"
    },
    {
      "name": "conditions",
      "type": "string",
      "required": false,
      "default": "",
      "description": "Comma-separated sample groups in count-matrix column order, e.g. 'control,control,treated,treated'. Required for the DESeq2 step; a single-sample run produces counts only."
    }
  ],
  "steps": [
    {
      "step": 1,
      "tool": "fastqc",
      "description": "Quality control of raw reads"
    },
    {
      "step": 2,
      "tool": "trimmomatic",
      "description": "Adapter trimming and quality filtering",
      "after": [
        "step1_fastqc"
      ]
    },
    {
      "step": 3,
      "tool": "hisat2",
      "description": "Splice-aware alignment to reference genome",
      "after": [
        "step2_trim"
      ]
    },
    {
      "step": 4,
      "tool": "samtools",
      "description": "Sort and index aligned BAM",
      "after": [
        "step3_align"
      ]
    },
    {
      "step": 5,
      "tool": "featurecounts",
      "description": "Count reads per gene against the GTF annotation, producing the count matrix",
      "after": [
        "step4_sort"
      ]
    },
    {
      "step": 6,
      "tool": "deseq2",
      "description": "Differential expression with DESeq2 from the count matrix (skipped when no conditions are supplied)",
      "after": [
        "step5_quantify"
      ]
    }
  ]
}

